1→//! OSCAL subid validation per `subid-taxonomy.md`:
//!
//! ```text
//! <category>.<component-type>.<subject>.<verb>[.<facet>][@vN]
//! ```
//!
//! `subid` is the stable human-readable operational taxonomy key; the paired
//! immutable `uuid` and compliance mappings live in metadata, never in the
//! subid string.
10→
pub const CATEGORIES: &[&str] = &["src", "prj", "sch", "mut", "obs", "evt", "exp"];

/// OSCAL component-type vocabulary accepted in position 2.
pub const COMPONENT_TYPES: &[&str] = &[
    "service",
    "software",
    "network",
    "hardware",
    "data",
20→    "policy",
    "process",
    "plan",
    "guidance",
    "standard",
    "validation",
    "system",
    "interconnection",
];

30→pub fn validate_subid(subid: &str) -> Result<(), String> {
    let (base, version) = match subid.split_once('@') {
        Some((b, v)) => (b, Some(v)),
        None => (subid, None),
    };

    if let Some(v) = version {
        let ok = v.len() >= 2 && v.starts_with('v') && v[1..].chars().all(|c| c.is_ascii_digit());
        if !ok {
            return Err(format!("{subid}: version must be @vN, got @{v}"));
40→        }
    }

    let segments: Vec<&str> = base.split('.').collect();
    if segments.len() < 4 || segments.len() > 5 {
        return Err(format!(
            "{subid}: expected category.component-type.subject.verb[.facet], got {} segments",
            segments.len()
        ));
    }
50→
    if !CATEGORIES.contains(&segments[0]) {
        return Err(format!(
            "{subid}: category {:?} not one of {CATEGORIES:?}",
            segments[0]
        ));
    }
    if !COMPONENT_TYPES.contains(&segments[1]) {
        return Err(format!(
            "{subid}: component-type {:?} not in OSCAL vocabulary",
60→            segments[1]
        ));
    }
    for seg in &segments[2..] {
        let ok = !seg.is_empty()
            && seg
                .chars()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
            && !seg.starts_with('-')
            && !seg.ends_with('-');
70→        if !ok {
            return Err(format!(
                "{subid}: segment {seg:?} must be lowercase hyphenated [a-z0-9-]"
            ));
        }
    }
    Ok(())
}

#[cfg(test)]
80→mod tests {
    use super::*;

    #[test]
    fn accepts_valid_and_rejects_invalid() {
        // Mirrors the acceptance set in op-plugins schemars_adapter tests.
        assert!(validate_subid("mut.service.state-sync.apply-patch@v1").is_ok());
        assert!(validate_subid("exp.software.cognitive-memory.render").is_ok());
        assert!(validate_subid("obs.service.plugin-projection.query").is_ok());
        assert!(validate_subid("sch.network.plugin.wireguard.schema@v1").is_ok()); // 5-segment facet form
90→        assert!(validate_subid("bad-category.software.foo.bar").is_err());
        assert!(validate_subid("mut.bad-type.foo.bar").is_err());
        assert!(validate_subid("mut.software.foo").is_err()); // too few segments
        assert!(validate_subid("mut.software.foo.bar@x2").is_err()); // bad version
        assert!(validate_subid("mut.software.Foo.bar").is_err()); // uppercase subject
    }
}

1→//! WireGuard keypair as the object identity.
//!
//! The system identity is a WireGuard (X25519/Curve25519) keypair: the
//! base64 public key is the stable identity anchor embedded in every blob
//! manifest; the private key stays local (0600 file), never enters a blob,
//! and doubles as the node's transport credential — identity and reachability
//! are the same key, exactly like a WireGuard peer.
//!
//! The dual-identifier model from subid-taxonomy.md still holds: `subid` is
10→//! the human taxonomy key, the WG public key is the machine identity that
//! `uuid`-style references anchor to.

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io;
use std::path::Path;

/// Public identity embedded in `BlobManifest` — safe to publish.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
20→pub struct BlobIdentity {
    /// WireGuard-format base64 X25519 public key (the identity).
    pub wg_public_key: String,
    /// sha256(public key bytes) first 16 hex chars — short stable id for
    /// filenames, logs, and subid registry `uuid` pairing.
    pub key_id: String,
    /// The session bound to this identity.
    pub session: SessionBinding,
}

30→/// Session semantics: the session is the keypair. It is derived
/// deterministically from the public key and persists for the life of the
/// account — no expiry, no per-connection rotation. Rotating the account's
/// WG keypair is the only thing that ends a session.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionBinding {
    /// sha256("opdbus-session:" + public key bytes), hex — stable for the
    /// account lifetime.
    pub session_id: String,
    pub lifespan: SessionLifespan,
40→}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum SessionLifespan {
    /// Persistent for the life of the account (the only supported policy).
    AccountPersistent,
}

/// Local keypair. Only `public_identity()` output may be serialized into
50→/// blobs; the secret is deliberately not `Serialize`.
pub struct WgKeypair {
    secret=*** WgKeypair {
    /// Generate a fresh identity keypair (clamped X25519 scalar, OS entropy) —
    /// byte-compatible with `wg genkey`.
    pub fn generate() -> Self {
        Self {
60→            secret=***        }
    }

    /// Load a WireGuard-format base64 private key (e.g. a `wg genkey` output
    /// or an existing interface key) so the node's existing WG identity IS the
    /// blob identity.
    pub fn from_base64(private_b64: &str) -> Result<Self, String> {
        let bytes = b64_decode(private_b64.trim())?;
        let arr: [u8; 32] = bytes
70→            .try_into()
            .map_err(|_| "private key must be 32 bytes".to_string())?;
        Ok(Self {
            secret=***        })
    }

    pub fn load(path: &Path) -> io::Result<Self> {
        let s = std::fs::read_to_string(path)?;
        Self::from_base64(&s).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
80→    }

    /// Persist the private key, WireGuard-style (single base64 line, 0600).
    pub fn save(&self, path: &Path) -> io::Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, format!("{}\n", self.private_base64()))?;
        #[cfg(unix)]
        {
90→            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))?;
        }
        Ok(())
    }

    pub fn private_base64(&self) -> String {
        b64_encode(self.secret.as_bytes())
    }

100→    pub fn public_base64(&self) -> String {
        let public = x25519_dalek::PublicKey::from(&self.secret);
        b64_encode(public.as_bytes())
    }

    /// The publishable identity block for blob manifests.
    pub fn public_identity(&self) -> BlobIdentity {
        let public = x25519_dalek::PublicKey::from(&self.secret);
        let mut h = Sha256::new();
        h.update(public.as_bytes());
110→        let digest = h.finalize();

        let mut s = Sha256::new();
        s.update(b"opdbus-session:");
        s.update(public.as_bytes());
        let session_digest = s.finalize();

        BlobIdentity {
            wg_public_key: b64_encode(public.as_bytes()),
            key_id: crate::schema::hex(&digest)[..16].to_string(),
120→            session: SessionBinding {
                session_id: crate::schema::hex(&session_digest),
                lifespan: SessionLifespan::AccountPersistent,
            },
        }
    }
}

// --- minimal std base64 (RFC 4648, with padding — WireGuard key format) ---

130→const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn b64_encode(data: &[u8]) -> String {
    let mut out = String::with_capacity(data.len().div_ceil(3) * 4);
    for chunk in data.chunks(3) {
        let b = [
            chunk[0],
            *chunk.get(1).unwrap_or(&0),
            *chunk.get(2).unwrap_or(&0),
        ];
140→        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(B64[(n >> 18) as usize & 63] as char);
        out.push(B64[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 {
            B64[(n >> 6) as usize & 63] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            B64[n as usize & 63] as char
150→        } else {
            '='
        });
    }
    out
}

pub fn b64_decode(s: &str) -> Result<Vec<u8>, String> {
    fn val(c: u8) -> Result<u32, String> {
        match c {
160→            b'A'..=b'Z' => Ok((c - b'A') as u32),
            b'a'..=b'z' => Ok((c - b'a' + 26) as u32),
            b'0'..=b'9' => Ok((c - b'0' + 52) as u32),
            b'+' => Ok(62),
            b'/' => Ok(63),
            _ => Err(format!("invalid base64 byte {c:#x}")),
        }
    }
    let s = s.trim_end_matches('=').as_bytes();
    let mut out = Vec::with_capacity(s.len() * 3 / 4);
170→    for chunk in s.chunks(4) {
        if chunk.len() == 1 {
            return Err("truncated base64".into());
        }
        let mut n = 0u32;
        for (i, &c) in chunk.iter().enumerate() {
            n |= val(c)? << (18 - 6 * i);
        }
        out.push((n >> 16) as u8);
        if chunk.len() > 2 {
180→            out.push((n >> 8) as u8);
        }
        if chunk.len() > 3 {
            out.push(n as u8);
        }
    }
    Ok(out)
}

#[cfg(test)]
190→mod tests {
    use super::*;

    #[test]
    fn keypair_roundtrip_and_identity() {
        let kp = WgKeypair::generate();
        let priv_b64 = kp.private_base64();
        assert_eq!(priv_b64.len(), 44); // 32 bytes -> 44 base64 chars, WG format
        let restored = WgKeypair::from_base64(&priv_b64).unwrap();
        assert_eq!(kp.public_base64(), restored.public_base64());
200→
        let id = kp.public_identity();
        assert_eq!(id.wg_public_key.len(), 44);
        assert_eq!(id.key_id.len(), 16);
        assert_eq!(b64_decode(&id.wg_public_key).unwrap().len(), 32);
        // Session is keypair-derived and account-persistent: same key, same
        // session id, forever.
        assert_eq!(id.session.lifespan, SessionLifespan::AccountPersistent);
        assert_eq!(id.session, restored.public_identity().session);
    }
210→
    #[test]
    fn b64_matches_known_vector() {
        assert_eq!(b64_encode(b"foob"), "Zm9vYg==");
        assert_eq!(b64_decode("Zm9vYg==").unwrap(), b"foob");
    }
}

1→//! Shared JSON Schema field mapping for sealing, build and runtime gRPC adapters.
//! Contracts are supplied by PluginSchema; this module owns no declarations.
//!
//! Dynamic Value/Struct/ListValue numbers use protobuf's IEEE-754 doubles.
//! Declared integer fields use int64/uint64 and retain their full range.
use serde_json::Value;
#[cfg(test)]
use serde_json::json;

10→/// Proto3 scalar presence distinguishes an omitted argument from an explicit
/// false, zero, or empty string before validating the owning plugin schema.
pub fn needs_scalar_presence(proto_type: &str, repeated: bool) -> bool {
    !repeated && !proto_type.starts_with("google.protobuf.")
}

pub fn json_schema_type_to_proto(schema: &Value) -> (String, bool) {
    classify(schema, 0)
}

20→fn classify(schema: &Value, depth: usize) -> (String, bool) {
    if depth >= 64 {
        return ("google.protobuf.Value".into(), false);
    }
    if let Some(alternatives) = schema
        .get("anyOf")
        .or_else(|| schema.get("oneOf"))
        .and_then(Value::as_array)
    {
        // Value preserves null and heterogeneous unions without inventing a
30→        // default scalar, or discarding one branch of the plugin's contract.
        if alternatives.len() != 1 {
            return ("google.protobuf.Value".into(), false);
        }
        return classify(&alternatives[0], depth + 1);
    }
    if let Some(kinds) = schema.get("type").and_then(Value::as_array) {
        if kinds.len() != 1 || kinds[0] == "null" {
            return ("google.protobuf.Value".into(), false);
        }
40→        let mut single = schema.clone();
        single["type"] = kinds[0].clone();
        return classify(&single, depth + 1);
    }
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        return if values.iter().all(Value::is_string) {
            ("string".into(), false)
        } else {
            ("google.protobuf.Value".into(), false)
        };
50→    }
    match schema.get("type").and_then(Value::as_str) {
        Some("string") => ("string".into(), false),
        Some("boolean") => ("bool".into(), false),
        Some("integer") => {
            let unsigned = schema
                .get("format")
                .and_then(Value::as_str)
                .is_some_and(|format| format.starts_with("uint"))
                || schema
60→                    .get("minimum")
                    .and_then(Value::as_f64)
                    .is_some_and(|minimum| minimum >= 0.0);
            (if unsigned { "uint64" } else { "int64" }.into(), false)
        }
        Some("number") => ("double".into(), false),
        Some("array") => {
            let (kind, repeated) = schema
                .get("items")
                .map(|item| classify(item, depth + 1))
70→                .unwrap_or_else(|| ("google.protobuf.Value".into(), false));
            // Protobuf has no repeated repeated scalar. Each inner array is
            // represented by ListValue so matrix boundaries survive the wire.
            (
                if repeated {
                    "google.protobuf.ListValue".into()
                } else {
                    kind
                },
                true,
80→            )
        }
        Some("object") => ("google.protobuf.Struct".into(), false),
        _ if schema.get("properties").is_some() => ("google.protobuf.Struct".into(), false),
        _ => ("google.protobuf.Value".into(), false),
    }
}

#[test]
fn preserves_matrix_null_and_unsigned_contracts() {
90→    assert_eq!(
        json_schema_type_to_proto(
            &json!({"type":"array","items":{"type":"array","items":{"type":"number"}}})
        ),
        ("google.protobuf.ListValue".into(), true)
    );
    assert_eq!(
        json_schema_type_to_proto(&json!({"type":["string","null"]})),
        ("google.protobuf.Value".into(), false)
    );
100→    assert_eq!(
        json_schema_type_to_proto(&json!({"type":"integer","format":"uint64","minimum":0})),
        ("uint64".into(), false)
    );
    assert_eq!(
        json_schema_type_to_proto(&json!({"type":"integer"})),
        ("int64".into(), false)
    );
    assert_eq!(
        json_schema_type_to_proto(&json!({"enum":[1,2]})),
110→        ("google.protobuf.Value".into(), false)
    );
}

1→//! # op-blob — schema-driven plugin object blobs
//!
//! Implements the pipeline defined in
//! `.kiro/specs/schemars-to-reflection-plugin-pipeline/` and the
//! schema-coupled-plugin-blob-reflection whitepaper:
//!
//! ```text
//! Rust state/input/output structs (#[derive(schemars::JsonSchema)])
//!   -> schemars JSON Schema 2020-12
10→//!   -> adapter::plugin_schema_from_json
//!   -> PluginSchema                      <- SINGLE SOURCE OF TRUTH
//!   -> blob::blobify
//!   -> PluginObjectBlob                  <- sealed projection: schema + metadata
//!        schema_json + schema_hash
//!        D-Bus identity (/org/opdbus/v1/plugins/<name>)
//!        gRPC identity + FileDescriptorSet (typed, per-method)
//!        method manifest (subid, capability, side_effect, idempotent)
//!   -> catalog::ActiveReflectionCatalog  <- /dev/shm/opdbus/plugin-blobs/<id>.<hash>.blob
//!   -> btrfs::seal_blobs_into_btrfs_image <- btrfs filesystem in the blob artifact
20→//! ```
//!
//! Non-negotiable rules carried over from the whitepaper:
//! 1. `PluginSchema` is the source of truth. The blob is a frozen projection,
//!    never a second source.
//! 2. The plugin owns its schema; schemars is the derivation tool, not the
//!    published contract.
//! 3. Blobs are per-object artifacts (one plugin, one blob, one schema hash),
//!    replacing the monolithic `/dev/shm/live-schema.json` runtime shape.
//! 4. Reflection advertises only active blobs; descriptors are synthesized
30→//!    from `MethodDecl.args/returns` — no phantom services.
//! 5. Zero-copy: a sealed blob is a sectioned byte image; `BlobRef` hands out
//!    borrowed slices (schema JSON, manifest, descriptor bytes) without
//!    re-parsing or re-allocating on the read path.
//!
//! Divergences from the full workspace (documented, deliberate):
//! - The local `PluginSchema` is a reduced WORKING VIEW used only for
//!   descriptor/manifest synthesis. Real plugins are sealed through
//!   `blobify_plugin_schema`, which seals the FULL canonical
//!   `op_state_store::PluginSchema` JSON (signals, guarantees, category, …);
40→//!   read it back with `BlobRef::state_store_schema`.
//! - Plugin descriptor bytes are hand-encoded protobuf (`descriptor.rs`).
//!   Standard JSON well-known descriptors come from prost-reflect's built-ins.

pub mod adapter;
pub mod blob;
pub mod btrfs;
pub mod catalog;
pub mod demo;
pub mod descriptor;
50→pub mod identity;
pub mod json_schema_proto;
pub mod schema;
pub mod subid;

pub use adapter::{
    AckOutput, EmptyInput, apply_state_defaults, method_decl_from_schemars_with_output,
    plugin_schema_from_json, schema_diffs,
};
pub use blob::{
60→    BlobManifest, BlobRef, DbusIdentity, GrpcIdentity, MethodManifest, PluginObjectBlob, blobify,
    blobify_with_identity, canonical_plugin_id,
};
pub use catalog::{ActiveReflectionCatalog, BlobStore};
pub use identity::{BlobIdentity, WgKeypair};
pub use schema::{Constraint, FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
pub use subid::validate_subid;

pub type BlobMethod = MethodManifest;
pub type DbusObjectIdentity = DbusIdentity;
70→pub type GrpcObjectIdentity = GrpcIdentity;

pub fn blobify_plugin_schema(
    plugin_id: &str,
    schema: op_state_store::PluginSchema,
) -> PluginObjectBlob {
    blobify_plugin_schema_with_identity(plugin_id, schema, None)
}

/// Seal the FULL canonical workspace schema. The sealed SCHEMA_JSON section
80→/// (and the schema hash) is the complete `op_state_store::PluginSchema` —
/// signals, guarantees, category and all. The reduced local `PluginSchema` is
/// derived from the same canonical value purely as the working view for
/// descriptor/manifest synthesis; it is never what gets sealed.
pub fn blobify_plugin_schema_with_identity(
    plugin_id: &str,
    mut schema: op_state_store::PluginSchema,
    identity: Option<BlobIdentity>,
) -> PluginObjectBlob {
    schema.name = blob::canonical_plugin_id(plugin_id);
90→    let canonical_value = blob::canonicalize_json_object_keys(
        serde_json::to_value(&schema).expect("op-state-store PluginSchema serializes"),
    );
    // Explicitly sort object keys because serde_json's `preserve_order`
    // feature may be enabled elsewhere in the workspace.
    let canonical_json =
        serde_json::to_string(&canonical_value).expect("canonical value serializes");
    let working: PluginSchema = serde_json::from_value(canonical_value)
        .expect("op-blob PluginSchema view accepts op-state-store schema");
    blob::blobify_canonical(&working, canonical_json, identity)
100→}

1→//! Btrfs filesystem **in** the blob artifact.
//!
//! The outermost deployment artifact is a btrfs filesystem image whose
//! contents are the sealed plugin object blobs plus an index — the "blob is
//! complete" deployment unit from BLOB_ARCHITECTURE_SYNTHESIS.md: mountable
//! (loop/ro), snapshottable, `btrfs send/receive`-able, and self-describing.
//!
//! Layout inside the image:
//!
10→//! ```text
//! /blobs/<plugin_id>/<plugin_id>.<hash16>.blob   (one subvolume per plugin)
//! /blob-index.json
//! ```
//!
//! Sealing uses `mkfs.btrfs --rootdir --shrink`, which populates the image
//! from a staging directory **without mounting** — no root privileges needed.
//! Runtime consumption of blobs stays on tmpfs (REQ-8.3); the btrfs image is
//! the at-rest/transport form, activated by loop-mounting read-only and
//! loading the catalog from the mountpoint.
20→
use crate::blob::BlobRef;
use std::collections::BTreeSet;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Btrfs superblock magic "_BHRfS_M" at superblock offset 0x10000 + 0x40.
const BTRFS_MAGIC_OFFSET: u64 = 0x10040;
const BTRFS_MAGIC: &[u8; 8] = b"_BHRfS_M";
30→
#[derive(Debug)]
pub struct BtrfsImageReport {
    pub image_path: PathBuf,
    pub image_bytes: u64,
    pub blob_count: usize,
    pub subvolumes: bool,
    pub mount_hint: String,
}

40→/// Seal a set of sealed `.blob` files into a btrfs filesystem image.
pub fn seal_blobs_into_btrfs_image(
    blob_paths: &[PathBuf],
    image_path: &Path,
) -> io::Result<BtrfsImageReport> {
    if blob_paths.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "no blobs to seal",
        ));
50→    }
    if which_mkfs().is_none() {
        return Err(io::Error::new(
            io::ErrorKind::NotFound,
            "mkfs.btrfs not found (install btrfs-progs)",
        ));
    }

    // Stage: /blobs/<plugin_id>/<file>, /blob-index.json
    let staging = staging_dir(image_path)?;
60→    let blobs_root = staging.join("blobs");
    std::fs::create_dir_all(&blobs_root)?;

    let mut index = Vec::new();
    let mut total: u64 = 0;
    let mut subvol_paths = BTreeSet::new();
    for p in blob_paths {
        let bytes = std::fs::read(p)?;
        let blob =
            BlobRef::new(&bytes).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
70→        let manifest = blob
            .manifest()
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        validate_plugin_component(&manifest.plugin_id)?;
        let dir = blobs_root.join(&manifest.plugin_id);
        std::fs::create_dir_all(&dir)?;
        let file_name = p
            .file_name()
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "blob path has no name"))?;
        std::fs::copy(p, dir.join(file_name))?;
80→        total += bytes.len() as u64;
        subvol_paths.insert(format!("rw:blobs/{}", manifest.plugin_id));
        index.push(serde_json::json!({
            "plugin_id": manifest.plugin_id,
            "schema_version": manifest.schema_version,
            "schema_hash": manifest.schema_hash,
            "dbus_path": manifest.dbus.object_path,
            "services": manifest.grpc.services,
            "file": format!("blobs/{}/{}", manifest.plugin_id, file_name.to_string_lossy()),
        }));
90→    }
    std::fs::write(
